"""src/evaluate.py
Unified evaluation logic shared by every experimental variant.
DO NOT edit evaluation metrics in downstream experiments – all variants MUST
be comparable and reproducible under the exact same evaluation criteria.
"""
from __future__ import annotations
from typing import Dict, Any

import torch
import torch.nn.functional as F
from torch_geometric.data import Data
from sklearn.metrics import accuracy_score, roc_auc_score


def _to_numpy(x: torch.Tensor):
    return x.detach().cpu().numpy()


class Evaluator:
    def __init__(self, data: Data):
        self.data = data
        # Decide whether to report accuracy or AUROC based on #classes
        self.metric = "accuracy" if int(data.y.max()) + 1 < 10 else "auroc"

    def _batch_iter(self, idx: torch.Tensor, bs: int):
        for i in range(0, idx.numel(), bs):
            yield idx[i : i + bs]

    def eval(self, model: torch.nn.Module, split: str = "test", batch_size: int = 4096):
        mask = getattr(self.data, f"{split}_mask")
        idx = mask.nonzero(as_tuple=False).view(-1)
        preds, labels = [], []
        for b in self._batch_iter(idx, batch_size):
            out = model(self.data.x[b])
            preds.append(out)
            labels.append(self.data.y[b])
        logits = torch.cat(preds, dim=0)
        y_true = torch.cat(labels, dim=0)

        if self.metric == "accuracy":
            y_hat = logits.argmax(dim=1)
            return accuracy_score(_to_numpy(y_true), _to_numpy(y_hat))
        else:
            if logits.shape[1] == 2:
                y_prob = F.softmax(logits, dim=1)[:, 1]
            else:
                y_prob = F.softmax(logits, dim=1)
            return roc_auc_score(_to_numpy(y_true), _to_numpy(y_prob),
                                 multi_class="ovr", average="macro")

