import torch, torch.nn.functional as F
from torch_geometric.loader import NeighborLoader
from fast_dpp import sample_k_dpp  # pip install fast-dpp

class MomentumCache:
    def __init__(self,beta=0.9):
        self.beta=beta; self.store={}
    def update(self,edges,alpha):
        # edges: [E,2] tensor, alpha: [E]
        for (i,j),a in zip(edges.tolist(),alpha.tolist()):
            key=(i,j)
            self.store[key]=self.beta*self.store.get(key,0.0)+(1-self.beta)*a
    def get(self,js):
        return torch.tensor([self.store.get(tuple(edge),0.0) for edge in js])

class DPABanditLayer:
    def __init__(self,k,eta=0.3,beta=0.9):
        self.k=k; self.eta=eta; self.w=None; self.cache=MomentumCache(beta)
    @torch.no_grad()
    def sample(self,cand_emb,cand_edges,grad,alpha_raw):
        # cand_emb: [m,d]   cand_edges: [m,2]
        if self.w is None:
            self.w=torch.ones(cand_emb.size(0),device=cand_emb.device)
        alpha=self.cache.get(cand_edges)
        reward=(-grad.abs()*alpha).cpu()
        p=(1-1e-3)*self.w/self.w.sum()+1e-3
        sel_idx=sample_k_dpp(cand_emb.cpu().numpy(),self.k)  # diversity step
        est=torch.zeros_like(p); est[sel_idx]=reward[sel_idx]/p[sel_idx]
        self.w*=torch.exp(self.eta*est.to(self.w.device))
        self.cache.update(cand_edges.cpu(),alpha_raw.cpu())
        return sel_idx

