# SW-DPP reservoir (PyTorch)
class SWDPP:
    def __init__(self,K,W,d):
        self.K,K0=K,K*3; self.W=W; self.d=d; self.res=[]
    def _sketch(self,emb):
        # CountSketch+RFF to 256 dims
        return torch.randn(self.d,256,device=emb.device)@emb.T
    def update(self,emb):
        self.res.append(self._sketch(emb))
        if len(self.res)>self.W: self.res.pop(0)
    def sample(self,cand_emb):
        R=torch.cat(self.res+[self._sketch(cand_emb)],1)
        K=(R.T@R)/(self.d)
        idx=fast_k_dpp(K,self.K)
        return idx

